static std::vector<size_t> widths(const std::vector<ScheduleNode>&nodes){
 std::vector<size_t>incoming(nodes.size());std::vector<std::set<uint32_t>>edges(nodes.size());
 for(size_t i=0;i<nodes.size();++i)for(const auto&group:nodes[i].edgeGroups)for(auto next:group){if(next>=nodes.size())throw std::runtime_error("bad dependency index");if(edges[i].insert(next).second)++incoming[next];}
 std::vector<uint32_t>ready;for(uint32_t i=0;i<nodes.size();++i)if(!incoming[i])ready.push_back(i);std::vector<size_t>result;size_t visited=0;
 while(!ready.empty()){result.push_back(ready.size());visited+=ready.size();std::vector<uint32_t>next;for(auto i:ready)for(auto j:edges[i])if(--incoming[j]==0)next.push_back(j);ready=std::move(next);}
 if(visited!=nodes.size())throw std::runtime_error("dependency cycle");return result;
}
