 auto typed=discoverSessionAdditionalPlayPathsCandidate(graph,root,discovery.chains);for(const auto&item:typed)plan.operations.push_back(channelOperation(item.first,ChannelBinding(graph,item.first)));
 auto colors=discoverSessionColorCopyChannelsCandidate(graph,root);std::set<uint32_t>packs;for(auto id:colors){ChannelBinding binding(graph,id);plan.operations.push_back(channelOperation(id,binding));packs.insert(binding.source.element);}for(auto id:packs)plan.operations.push_back(packColorOperationCandidate(graph,id));
 std::set<uint32_t>ids;for(const auto&operation:plan.operations)if(!ids.insert(operation.id).second)throw std::runtime_error("duplicate operation");auto nodes=attributeDependencies(plan.operations);auto frontier=widths(nodes);size_t total=0,maximum=0;for(auto width:frontier){total+=width;maximum=std::max(maximum,width);}if(total!=plan.operations.size())throw std::runtime_error("lost operation");
 std::vector<uint32_t>roots;for(uint32_t i=0;i<nodes.size();++i)roots.push_back(i);auto serial=traverseSchedule(nodes,roots);if(serial.cycle)throw std::runtime_error("access schedule cycle");
 auto accessLayers=declaredAccessLayersCandidate(plan.operations,serial.order);size_t accessMaximum=0;for(const auto&layer:accessLayers)accessMaximum=std::max(accessMaximum,layer.size());
 std::cout<<"declared_access_layers="<<accessLayers.size()<<" maximum_frontier="<<accessMaximum<<" preserves_declared_serial_hazards=1 hidden_reads_and_aliases=unproved execution=not_performed\n";
 if(scalarSamplingReadSetStableCandidate(1,{{2,"source"}},{{{2,"source"},{3}}})||!scalarSamplingReadSetStableCandidate(1,{{2,"source"}},{{{2,"source"},{1}}})||!scalarSamplingReadSetStableCandidate(1,{{2,"source"}},{}))throw std::runtime_error("read guard checks failed");size_t admitted=0,rejectedReads=0;size_t fallbackReads=0,fallbackReadsWithWriters=0;std::map<AttributeIdentity,std::vector<uint32_t>>writers;for(const auto&operation:plan.operations)for(const auto&output:operation.outputs)writers[output].push_back(operation.id);for(const auto&operation:plan.operations){if(graph.strings.at(graph.elements.at(operation.id).type)!="DmeChannel")continue;ChannelBinding binding(graph,operation.id);if(binding.mode!=3||binding.destination.scalarType!=3||binding.log==0xffffffff)continue;if(scalarSamplingReadSetStableCandidate(operation.id,scalarSamplingReadsCandidate(graph,operation.id,binding),writers))++admitted;else ++rejectedReads;FloatLogDefault defaults(graph,graph.elements.at(binding.log));auto path=channelPlayPath(true,true,false,sessionFloatLogEmpty(graph,binding.layers),defaults.enabled,binding.source.present());if(path!=ChannelPlayPath::CopySource)continue;++fallbackReads;auto found=writers.find({binding.source.element,binding.source.attribute});if(found!=writers.end())for(auto writer:found->second)if(writer!=operation.id){++fallbackReadsWithWriters;break;}}std::cout<<"scalar_stable_reads_admitted="<<admitted<<" rejected="<<rejectedReads<<'\n';std::cout<<"scalar_fallback_reads="<<fallbackReads<<" fallback_reads_with_other_writers="<<fallbackReadsWithWriters<<" mode3_source_edges_omitted=1\n";std::cout<<"operations="<<total<<" dependency_layers="<<frontier.size()<<" maximum_frontier="<<maximum<<" widths=";for(auto width:frontier)std::cout<<width<<',';std::cout<<" attribute_edges_only=1 shared_mutation_safety=unproved execution=not_performed\n";return 0;
